import Foundation
struct PracticeEntry: Codable { let title: String; let minutes: Int }
struct LoadResult { let entries: [PracticeEntry]; let message: String }
func loadEntries(_ data: Data) -> LoadResult {
    do {
        let entries = try JSONDecoder().decode([PracticeEntry].self, from: data)
        return LoadResult(entries: entries, message: "Loaded")
    } catch {
        return LoadResult(entries: [], message: "Data could not be read")
    }
}
func loadEntries(from url: URL) -> LoadResult {
    do { return loadEntries(try Data(contentsOf: url)) }
    catch { return LoadResult(entries: [], message: "File could not be read") }
}
let bytes = Data("[{\"title\":\"Map\",\"minutes\":5}]".utf8)
let url = FileManager.default.temporaryDirectory.appendingPathComponent("worked-overloads.json")
try bytes.write(to: url, options: .atomic)
print(loadEntries(bytes).entries.count)
print(loadEntries(from: url).entries.count)
print(loadEntries(Data("broken".utf8)).entries.count)

struct LookupResult {
    let index: Int?
    let comparisons: Int
}

func locate(_ target: Int, in values: [Int]) -> LookupResult {
    var comparisons = 0
    for (index, value) in values.enumerated() {
        comparisons += 1
        if value == target {
            return LookupResult(index: index, comparisons: comparisons)
        }
    }
    return LookupResult(index: nil, comparisons: comparisons)
}

let values = [4, 8, 12, 16]
let found = locate(12, in: values)
let missing = locate(20, in: values)
print(found.index ?? -1)
print(found.comparisons)
print(missing.index == nil)
print(missing.comparisons)

struct Result {
    let index: Int?
    let comparisons: Int
}
func search(_ target: Int, in values: [Int]) -> Result {
    var count = 0
    for (index, value) in values.enumerated() {
        count += 1
        if value == target {
            return Result(index: index, comparisons: count)
        }
    }
    return Result(index: nil, comparisons: count)
}

let short = Array(0..<6)
let long = Array(0..<12)
let first = search(0, in: short)
let smallLast = search(5, in: short)
let largeLast = search(11, in: long)
let absent = search(-1, in: short)
assert(first.index == 0 && first.comparisons == 1)
assert(smallLast.index == 5 && smallLast.comparisons == 6)
assert(largeLast.comparisons == smallLast.comparisons * 2)
assert(absent.index == nil && absent.comparisons == short.count)
print("The small search checks passed")

